import React, { useId } from 'react';
import { chakra, Drawer, DrawerOverlay, useMultiStyleConfig, useModalContext, ModalFocusScope } from '@chakra-ui/react';
import type { SystemStyleObject } from '@chakra-ui/react';
import { motion } from 'framer-motion';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';

const ZIMM_DRAWER_RECIPE = 'ZimmDrawer';

// framer-motion's `Transition.ease` wants a literal, mutable 4-tuple (`BezierDefinition`) — a
// plain array literal infers as `number[]`, and `as const` infers a *readonly* tuple, neither of
// which satisfies it, hence the explicit cast.
const BEZIER_SLIDES_EASING = [0.87, 0, 0.13, 1] as [number, number, number, number];
// Mirrors theme/foundation/motion.ts's `duration.default` (300ms) and `easing.slides`
// (cubic-bezier(0.87, 0, 0.13, 1), "panels and overlays entering the screen") — hand-converted
// to framer-motion's shape (seconds, not ms; a bezier tuple, not a CSS `cubic-bezier()` string)
// since motion.ts's tokens are CSS-string form and framer-motion doesn't accept that form. One
// shared value for both enter and exit — that symmetry is the whole point (SFCC-898).
const DRAWER_TRANSITION = { duration: 0.3, ease: BEZIER_SLIDES_EASING };

// `motion(chakra.div)` — framer OUTSIDE, chakra INSIDE. This ordering matters: framer's
// `motion()` only intercepts its own known animation props (initial/animate/exit/transition/
// variants) and forwards everything else straight to the wrapped component, so `transition`
// reaches framer-motion directly here. Chakra's OWN internal Drawer does the reverse
// (`chakra(Slide)`) — chakra wraps the animated component — and chakra's `shouldForwardProp`
// treats any prop literally named `transition` as a CSS shorthand style prop (it's a real
// Chakra/styled-system prop name), silently swallowing it before it ever reaches the wrapped
// component's real props (confirmed directly in @chakra-ui/system's should-forward-prop.js).
// That's why `<DrawerContent transition={...}>` had no effect and why this file no longer uses
// Chakra's `<DrawerContent>` at all — SFCC-898's close-animation defect (asymmetric enter/exit;
// Chakra's own Slide defaults to a spring-physics enter vs. a fixed 150ms tween exit, per
// @chakra-ui/transition's slide.js) can't be fixed through any prop that component exposes.
const MotionChakraDiv = motion(chakra.div);

// Matches Figma's own named drawer sizes exactly (SFCC-898) — see zimmDrawer.css.ts's
// file-level comment for the width/usage table. `xLarge` has no consumer yet (Cart is a full
// page today, not a drawer).
export type ZimmDrawerSize = 'large' | 'tablet' | 'small' | 'xLarge' | 'mobile' | 'prompt';

type ZimmDrawerBaseProps = {
  /** Whether the drawer is open. */
  isOpen: boolean;
  /** Called on backdrop click, Escape, and the close button (all via Chakra's Drawer). */
  onClose: () => void;
  /** Desktop/tablet width variant — see ZimmDrawerSize. Collapses to the mobile treatment
   *  below the tablet breakpoint regardless of which value is chosen — see zimmDrawer.css.ts. */
  size: ZimmDrawerSize;
  children: React.ReactNode;
  /** Text style for the title. 'large' applies heading1 (24px, uppercase, Futura Round regular);
   *  'small' applies body2Strong (14px bold). Defaults to 'large'. Only relevant when `title`
   *  is provided. */
  titleStyle?: 'large' | 'small';
  /** Element to focus when the drawer closes. Use when the trigger may not have received
   *  keyboard focus before opening (e.g. mouse click) — without this Chakra falls back to
   *  document.body and AC10 focus-return fails. */
  finalFocusRef?: React.RefObject<HTMLElement>;
  /** Element to focus when the drawer opens. Overrides Chakra's default (first focusable element
   *  in the panel, usually the close button) — use to land focus directly on the primary input. */
  initialFocusRef?: React.RefObject<HTMLElement>;
};

/**
 * Exactly one of:
 * - `title`       — renders an inline header row (title left, close button right); the drawer's
 *                   accessible name is derived from the rendered title element automatically.
 * - `labelledBy`  — ID of an existing element that labels the drawer (e.g. ZimmPdpDrawer's own
 *                   tab header). Paired with the floating close button.
 * - `aria-label`  — explicit string label when neither a visible title nor a separate element
 *                   is available.
 */
type ZimmDrawerProps = ZimmDrawerBaseProps &
  (
    | { title: string; labelledBy?: never; 'aria-label'?: never }
    | { title?: never; labelledBy: string; 'aria-label'?: never }
    | { title?: never; labelledBy?: never; 'aria-label': string }
  );

// Deliberately not named `ZimmDrawerContentProps` — scripts/generateRegistry.mjs's
// extractTsProps merges every `*Props`-suffixed type in a file into one component's registry
// row when it can't isolate the preferred one (ZimmDrawerProps' multi-line union body isn't
// matched by its regex, which can't cross a newline — a documented limitation, not a bug to
// patch there). That merge was leaking this internal helper's own fields (ariaLabel,
// contentStyles, closeButtonStyles) into ZimmDrawer's public registry entry.
type ZimmDrawerContentConfig = {
  children: React.ReactNode;
  onClose: () => void;
  /** Renders an inline header row (title left, close button right) instead of the floating
   *  close button when provided — see ZimmDrawerProps' `title` member. */
  title?: string;
  titleId?: string;
  titleStyle?: 'large' | 'small';
  labelledBy?: string;
  ariaLabel?: string;
  contentStyles: SystemStyleObject;
  headerStyles: SystemStyleObject;
  headerTitleStyles: SystemStyleObject;
  closeButtonStyles: SystemStyleObject;
};

/**
 * Replaces Chakra's own `<DrawerContent>` — see the `MotionChakraDiv` comment above for why.
 * Reuses Chakra's real dialog/focus/aria mechanics directly (`useModalContext`,
 * `ModalFocusScope` — both genuinely public exports, not reaching into Chakra internals) so
 * focus trap, initial focus, focus restore, body-scroll lock, and Escape/overlay-click-to-close
 * all still come from Chakra exactly as before; only the slide transition itself is now ours.
 *
 * Renders either an inline title row (title left, close button right) when `title` is passed, or
 * a floating close button only — see ZimmDrawer's own docblock for when each is used.
 *
 * @param props see ZimmDrawerContentConfig
 */
const ZimmDrawerContent = ({
  children,
  onClose,
  title,
  titleId,
  titleStyle = 'large',
  labelledBy,
  ariaLabel,
  contentStyles,
  headerStyles,
  headerTitleStyles,
  closeButtonStyles,
}: ZimmDrawerContentConfig) => {
  const { getDialogProps, getDialogContainerProps } = useModalContext();
  const dialogProps = getDialogProps({ 'aria-label': ariaLabel });
  // getDialogProps always computes `aria-labelledby` from Chakra's own <DrawerHeader> mount
  // state, which ZimmDrawer never renders (no header sub-component in this tree) — so it
  // always resolves to undefined regardless of what's passed in above. Set it directly so the
  // `title` and `labelledBy` prop variants of ZimmDrawerProps actually work.
  if (title && titleId) {
    dialogProps['aria-labelledby'] = titleId;
  } else if (labelledBy) {
    dialogProps['aria-labelledby'] = labelledBy;
  }
  const containerProps = getDialogContainerProps();

  return (
    <ModalFocusScope>
      <chakra.div {...containerProps} __css={{ position: 'fixed', inset: 0, display: 'flex', zIndex: 'modal' }}>
        <MotionChakraDiv
          {...dialogProps}
          initial={{ x: '100%' }}
          animate={{ x: 0 }}
          exit={{ x: '100%' }}
          transition={DRAWER_TRANSITION}
          __css={{ position: 'fixed', top: 0, right: 0, bottom: 0, outline: 0, ...contentStyles }}
        >
          {title ? (
            <chakra.div sx={headerStyles}>
              <chakra.span
                id={titleId}
                sx={headerTitleStyles}
                textStyle={titleStyle === 'small' ? 'body2Strong' : 'heading1'}
              >
                {title}
              </chakra.span>
              <ZimmButton variant="icon" icon="close" label="Close" onClick={onClose} />
            </chakra.div>
          ) : (
            <chakra.div sx={closeButtonStyles}>
              <ZimmButton variant="icon" icon="close" label="Close" onClick={onClose} />
            </chakra.div>
          )}
          {children}
        </MotionChakraDiv>
      </chakra.div>
    </ModalFocusScope>
  );
};

/**
 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Figma-matched size
 * variant (see ZimmDrawerSize), built on Chakra's Drawer primitive (focus trap, initial focus,
 * focus restore, body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not
 * hand-rolled).
 *
 * Pass `title` to render an inline header row (title text left, close button right) sized per the
 * Figma drawer/header frames. Omit `title` and pass `labelledBy`/`aria-label` instead for drawers
 * that supply their own header (e.g. ZimmPdpDrawer's tab row), which keeps the floating close
 * button behaviour.
 *
 * @param props see ZimmDrawerProps
 */
export const ZimmDrawer = (props: ZimmDrawerProps) => {
  const { isOpen, onClose, size, children, titleStyle = 'large', finalFocusRef, initialFocusRef } = props;
  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
  const titleId = useId();

  const title = 'title' in props ? props.title : undefined;
  const labelledBy = !title && 'labelledBy' in props ? props.labelledBy : undefined;
  const ariaLabel = !title && 'aria-label' in props ? props['aria-label'] : undefined;

  // Chakra's FocusLock remains active during the exit animation, so any focus call made
  // while the drawer is still mounted (rAF, close-button onClick) gets trapped and dropped.
  // onCloseComplete fires after the animation finishes and FocusLock is released — the only
  // reliable moment to restore focus. Covers both close-button click and Escape for all
  // consumers that pass finalFocusRef.
  const handleCloseComplete = () => {
    if (finalFocusRef) finalFocusRef.current?.focus();
  };

  return (
    <Drawer
      isOpen={isOpen}
      onClose={onClose}
      placement="right"
      onCloseComplete={handleCloseComplete}
      initialFocusRef={initialFocusRef}
    >
      <DrawerOverlay sx={styles.overlay} />
      {/* aria-labelledby (not aria-label) for the title case: Chakra's own <DrawerContent>
          would clobber it with its own headingId (undefined without a DrawerHeader), but
          ZimmDrawerContent bypasses <DrawerContent> entirely and sets dialogProps itself
          (see its own comment above) — the clobbering bug this would otherwise work around
          doesn't apply here, so referencing the visible title node is safe and preferred. */}
      <ZimmDrawerContent
        onClose={onClose}
        title={title}
        titleId={title ? titleId : undefined}
        titleStyle={titleStyle}
        labelledBy={labelledBy}
        ariaLabel={ariaLabel}
        contentStyles={styles.content}
        headerStyles={styles.header}
        headerTitleStyles={styles.headerTitle}
        closeButtonStyles={styles.closeButton}
      >
        {children}
      </ZimmDrawerContent>
    </Drawer>
  );
};

import { breakpoints } from 'app/theme/foundation';
import { DRAWER_HEADER_ROW_HEIGHT } from 'app/theme/components/zimmDrawerShared';

// Figma's actual named drawer sizes (SFCC-898) — five named sizes, not the three/four this
// file previously guessed at. Each name below matches Figma's own naming exactly, so there's
// no re-deriving which number belongs to which concept next time this file is touched:
//
//   Desktop Large — 50%  — Product Details, Filters (desktop width)
//   Tablet        — 80%  — Product Details, Filters (tablet width)
//   Desktop Small — 25%  — Notify Me, Wishlist, Find in Boutique, Regional Storefront,
//                           Cookies, Login
//   X-Large       — 82%  — Cart (not yet built as a drawer — see the `xLarge` variant below)
//   Mobile        — unchanged, the baseStyle treatment every variant collapses to below `md`.
//
// An earlier revision of this file measured 82% off a Figma frame annotated "Tablet = 82% of
// screen" and used it as `small`'s (now `tablet`'s) value — that frame's annotation was wrong
// (or superseded): 82% is actually X-Large's value (Cart), a completely different drawer this
// codebase hasn't built yet, and Tablet is genuinely 80%. Corrected once confirmed directly
// against the list above, not another single frame's own label.
const WIDTH_LARGE = '50%';
const WIDTH_TABLET = '80%';
// The original width set when this drawer shell was first built (2026-08-27) — matches Figma's
// "Desktop Small" exactly. Used by every viewport-independent narrow utility drawer (Find in
// Boutique today; Notify Me/Wishlist/Regional Storefront/Cookies/Login once those exist).
const WIDTH_SMALL = '25%';
// Cart isn't built as a drawer yet (confirmed: it's a full page today) — this constant and the
// `xLarge` variant below exist so the real Figma value is already in place, under the right
// name, whenever that work starts, rather than needing this same "which number is this?"
// investigation again.
const WIDTH_XLARGE = '82%';

// SFCC-831 — Figma-confirmed narrow-panel width floor (402px), the language/country-mismatch
// prompt's own precondition and the fix for a pre-existing defect: `small`'s 25% only reaches
// its designed 402px at a 1608px viewport, so every laptop under that width renders narrower
// than intended. rem, not px, so the floor still scales with browser zoom the way a fixed panel
// width should. No --zimm-scale equivalent exists yet.
const PANEL_MIN_NARROW = '25.125rem'; // 402px — audit-allow: provisional — pending a --zimm-* foundation token

// Shared by every narrow-panel variant (`small`, `prompt`) above `md`, same technique as
// INSET_COMPACT/INSET_LARGE above, so the width/floor/cap triple can't drift between them the
// way three independently-typed literals would. `maxWidth: '100%'` (not WIDTH_SMALL's own 25%)
// because the minWidth floor would otherwise fight a 25% cap below 1608px.
const NARROW_WIDTH_ABOVE_MD = { width: WIDTH_SMALL, minWidth: PANEL_MIN_NARROW, maxWidth: '100%' };

// Mobile deliberately leaves a strip of backdrop visible below the panel (SFCC-736 AC 9,
// PO-approved 2026-08-21 — "so a user can easily navigate out"). Re-measured against node
// 40002218:42903 (SFCC-898): overlay 956px tall, panel 898px tall — exactly 58px. No named
// spacing scale step lands on 58px, so this is a provisional raw value pending a foundation
// token, same as the other pending constants in this file.
const MOBILE_BOTTOM_GAP = '3.625rem'; // 58px

// Close-button inset, measured from the pdp/drawer header frames. `tablet`/`small`/`xLarge`/
// `mobile` all share the same measured inset (32px/40px) at every width — only `large` switches
// to the wider 48px/64px inset, at/above the tablet breakpoint. Below that breakpoint `large`'s
// own override doesn't apply either, and the baseStyle inset is used instead, which is also how
// the whole drawer collapses to the mobile treatment on a narrow viewport regardless of `size`.
const INSET_COMPACT = { top: 'var(--zimm-scale-3xl)', right: 'var(--zimm-scale-2xl)' };
const INSET_LARGE = { top: 'var(--zimm-scale-1200)', right: 'var(--zimm-scale-4xl)' };

// Header constants — from Figma drawer/header frame measurements.
// Compact horizontal inset (small/mobile): px=32px. Large desktop: px=64px.
// Small desktop header uses py=24px. Large desktop: container height=120px (row centred).
// Mobile base: container height=72px.
const HEADER_PADDING_COMPACT_X = 'var(--zimm-scale-2xl)'; // 32px
const HEADER_PADDING_LARGE_X = 'var(--zimm-scale-4xl)'; // 64px
const HEADER_PADDING_Y = 'var(--zimm-scale-xl)'; // 24px — small desktop py
// audit-allow: Figma-confirmed container heights with no --zimm-scale equivalents at these values.
const HEADER_HEIGHT_LARGE = '120px';
const HEADER_HEIGHT_MOBILE = '72px';

export const ZimmDrawer = {
  parts: ['overlay', 'content', 'closeButton', 'header', 'headerTitle'],
  baseStyle: {
    // Explicit position/inset rather than relying on Chakra's own built-in `Drawer` overlay
    // styling — confirmed via inspection that it doesn't apply (renders `position: static`,
    // zero size) when the `<Drawer>` isn't given Chakra's own `size` prop, which this component
    // deliberately omits (see maxWidth note below). Owning it here avoids depending on that.
    overlay: {
      position: 'fixed',
      inset: 0,
      background: 'var(--zimm-color-opacity-50)',
      zIndex: 'overlay',
    },
    content: {
      // Chakra's own <DrawerContent> baked in a default white background
      // (@chakra-ui/theme's modal.js `baseStyleDialog`: `bg: colors.white`) that this recipe
      // never needed to set itself while that component was still in use — now that
      // ZimmDrawer hand-rolls its own content element (see index.tsx's file-level comment),
      // nothing supplies one unless it's set here. Matches Figma's pdp/drawer panel background
      // (bg-[var(--brand/color/palette/white,white)]) — --zimm-color-bg-07 resolves to the
      // same grey.white value (SFCC-898 — the panel briefly had no background at all).
      background: 'var(--zimm-color-bg-07)',
      width: '100%',
      // Matches `width` at every step below — Chakra's own `Drawer` theme defaults to
      // `size="xs"` (maxW 20rem) when no `size` prop is passed to `<Drawer>` (deliberate: its
      // fixed size scale has no 50%/25% steps), and that default `maxW` otherwise still caps
      // our own `width` override since we never reset it.
      maxWidth: '100%',
      // A `height` reduction, not a `bottom` offset — Chakra's own Slide transition (see
      // @chakra-ui/transition's slide.js `placement: 'right'` case) pins the sliding wrapper
      // with `position: fixed; top: 0; right: 0; bottom: 0`, a definite height. `bottom` on
      // this `position: relative` DrawerContent just shifts the box within that instead of
      // reliably opening a gap (SFCC-898 — mobile bottom gap wasn't rendering at all); a
      // percentage `height` resolves cleanly against that definite-height ancestor instead.
      height: `calc(100% - ${MOBILE_BOTTOM_GAP})`,
      // Header stays fixed; only the content area (ZimmPdpDrawer's own `content` part) scrolls —
      // AC 10, "content area scrolls independently without the tab header scrolling".
      display: 'flex',
      flexDirection: 'column',
      overflow: 'hidden',
    },
    // Was missing `position: absolute` since this component's original commit — the
    // top/right insets below were silently no-ops (closeButton rendered as a normal in-flow
    // block instead of overlaying the header's corner), which is the root cause of SFCC-898's
    // close-button-misaligned-with-tabs defect across every breakpoint.
    //
    // height/display/alignItems/justifyContent: matches zimmTabs.css.ts's `menu.minHeight`
    // (DRAWER_HEADER_ROW_HEIGHT, zimmDrawerShared.ts) and centers the icon inside it — the
    // close icon's own intrinsic size doesn't equal the tab row's real rendered height, so
    // matching only `top` between the two (as before) left their vertical centers slightly
    // offset (SFCC-898, mobile). Only applies to the floating close button (no `title` passed) —
    // the inline title-row close button below is a normal flex child, not absolutely positioned.
    closeButton: {
      position: 'absolute',
      ...INSET_COMPACT,
      height: DRAWER_HEADER_ROW_HEIGHT,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    },
    // Drawer header — title (flex-1, left) + close button (right).
    // baseStyle applies the mobile/compact treatment: px=32px, container h=72px centred.
    header: {
      display: 'flex',
      alignItems: 'center',
      gap: 'var(--zimm-scale-xs)',
      backgroundColor: 'var(--zimm-color-text-inverse)',
      paddingInline: HEADER_PADDING_COMPACT_X,
      paddingBlock: 0,
      minHeight: HEADER_HEIGHT_MOBILE,
      flexShrink: 0,
    },
    headerTitle: {
      flex: '1 0 0',
      minWidth: 0,
      overflow: 'hidden',
      whiteSpace: 'nowrap',
    },
  },
  variants: {
    large: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_LARGE,
          maxWidth: WIDTH_LARGE,
          height: '100%',
        },
      },
      closeButton: {
        [`@media (min-width: ${breakpoints.md})`]: INSET_LARGE,
      },
      header: {
        [`@media (min-width: ${breakpoints.md})`]: {
          paddingInline: HEADER_PADDING_LARGE_X,
          minHeight: HEADER_HEIGHT_LARGE,
        },
      },
    },
    // Figma's "Tablet" size — the tablet-range step for Product Details/Filters, which
    // graduates to `large` (Desktop Large) at the desktop breakpoint via the caller's own
    // useBreakpointValue (ZimmPdpDrawer never selects this variant itself).
    tablet: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_TABLET,
          maxWidth: WIDTH_TABLET,
          height: '100%',
        },
      },
    },
    // Figma's "Desktop Small" — always narrow, at every width above the mobile collapse. No
    // js-level graduation to another variant the way `tablet` graduates to `large` — this is
    // the whole point for its utility-drawer consumers (Find in Boutique today).
    small: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          ...NARROW_WIDTH_ABOVE_MD,
          height: '100%',
        },
      },
    },
    // SFCC-831 — the country/language mismatch prompt. Below `md` it sizes to its own content
    // (a short banner, not a viewport-relative panel) capped by the same MOBILE_BOTTOM_GAP the
    // baseStyle content height already reserves, and scrolls internally if content overflows
    // that cap. Above `md` it becomes a normal narrow utility drawer — same width/floor as
    // `small` — with a full-height panel, matching every other size variant's shape there.
    prompt: {
      content: {
        height: 'auto',
        maxHeight: `calc(100% - ${MOBILE_BOTTOM_GAP})`,
        overflowY: 'auto',
        [`@media (min-width: ${breakpoints.md})`]: {
          ...NARROW_WIDTH_ABOVE_MD,
          height: '100%',
          maxHeight: '100%',
        },
      },
    },
    // Figma's "X-Large" (Cart) — not consumed anywhere yet (Cart is a full page today, not a
    // drawer), but the real value is already here under the right name for when that changes.
    xLarge: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_XLARGE,
          maxWidth: WIDTH_XLARGE,
          height: '100%',
        },
      },
      header: {
        [`@media (min-width: ${breakpoints.md})`]: {
          minHeight: 'unset',
          paddingBlock: HEADER_PADDING_Y,
        },
      },
    },
    // No override — the baseStyle above already is the mobile treatment.
    mobile: {},
  },
};

