 * a recipe that was never changed, which is exactly why each assertion below was proven red
 * against the pre-change recipe first (see the step's fail-on-purpose sub-step), then reverted.
 */

const MD_QUERY = `@media (min-width: ${breakpoints.md})`;

/**
 * `prompt.content`'s inferred type unions every property VALUE in the object — the plain
 * strings from its own base-level `height`/`maxHeight`/`overflowY` alongside the computed
 * `@media` key's own object value — because TypeScript synthesises one index-signature value
 * type across an object literal that mixes named string props with a single non-literal
 * computed key (`small.content`, which has no named props at that level, doesn't hit this; see
 * footer.css.ts's `subscribe` part for the identical mixed shape in production code, unaffected
 * only because it isn't read back here through a type-checked index). Narrows with a real type
 * guard rather than an `as` cast, per typescript.md's preference for `unknown` + a guard over an
 * assertion.
 */
const isMediaQueryStyles = (value: unknown): value is Record<string, string> =>
  typeof value === 'object' && value !== null;

const stylesAboveMd = (content: Record<string, unknown>): Record<string, string> => {
  const value = content[MD_QUERY];
  if (!isMediaQueryStyles(value)) {
    throw new Error(`expected "${MD_QUERY}" to resolve to a style object, got ${typeof value}`);
  }
  return value;
};

describe('ZimmDrawer — narrow-panel width floor (small, prompt share one 402px floor)', () => {
  test('small emits the 402px minWidth floor above md', () => {
    expect(stylesAboveMd(ZimmDrawer.variants.small.content).minWidth).toBe('25.125rem');
  });

  test('prompt emits the same 402px minWidth floor above md', () => {
    expect(stylesAboveMd(ZimmDrawer.variants.prompt.content).minWidth).toBe('25.125rem');
  });

  test('small no longer caps at the old 25% maxWidth (width itself, WIDTH_SMALL, is untouched)', () => {
    const aboveMd = stylesAboveMd(ZimmDrawer.variants.small.content);
    expect(aboveMd.width).toBe('25%');
    expect(aboveMd.maxWidth).not.toBe('25%');
    expect(aboveMd.maxWidth).toBe('100%');
  });
});

describe('ZimmDrawer — prompt size (sizes to its own content below md, full-height panel above)', () => {
  test('base level: auto height, capped by the mobile-bottom-gap calc(), scrolls internally', () => {
    const base = ZimmDrawer.variants.prompt.content;
    expect(base.height).toBe('auto');
    expect(base.maxHeight).toBe('calc(100% - 3.625rem)');
    expect(base.overflowY).toBe('auto');
  });

  test('above md: full height, maxHeight resets to 100% (no calc() cap)', () => {
    const aboveMd = stylesAboveMd(ZimmDrawer.variants.prompt.content);
    expect(aboveMd.height).toBe('100%');
    expect(aboveMd.maxHeight).toBe('100%');
  });
});

describe('ZimmDrawer — parts array is unchanged by this step', () => {
  test('no new recipe part was introduced', () => {
    expect(ZimmDrawer.parts).toEqual(['overlay', 'content', 'closeButton', 'header', 'headerTitle']);
  });
});

