import React, { useCallback, useEffect, useRef, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
import type { ZimmDrawerSize } from 'app/components/ui-kits/atoms/zimmDrawer';

const ZIMM_TABS_RECIPE = 'ZimmTabs';

export type ZimmTabItem = {
  /** Stable id used for activeTabId and the onTabChange callback. */
  id: string;
  /** Visible label — Contentful-driven per tab, so length varies and drives the overflow check. */
  label: string;
};

type ZimmTabsProps = {
  tabs: ZimmTabItem[];
  activeTabId: string;
  onTabChange: (id: string) => void;
  /** Matches the parent ZimmDrawer's size, so header padding stays in sync at every breakpoint. */
  size: ZimmDrawerSize;
  /** Accessible name for the `tablist` itself — WAI-ARIA's Tabs pattern requires one whenever
   *  there's no visible on-page label for the tab list (there isn't one here). The caller's own
   *  dialog `aria-label` is a reasonable value to reuse, per ZimmPdpDrawer. */
  ariaLabel: string;
  /**
   * Shared id prefix this tablist's tab buttons derive their own `id`/`aria-controls` from —
   * `${idPrefix}-tab-${tab.id}` / `${idPrefix}-panel`. The caller (ZimmPdpDrawer) uses the same
   * prefix for its panel's `id`/`aria-labelledby`, so the two stay in sync without either side
   * needing to know the other's internals. Generate with React's `useId()` at the call site so
   * ids are unique even with more than one tabbed drawer mounted at once.
   */
  idPrefix: string;
};

/**
 * Generic tab switcher — a row of tab buttons with width-based overflow: chevrons render only
 * when the next tab doesn't fit in the available width, and scroll the list by one tab per
 * click. Left/Right/Home/End move both focus and selection between tabs (WAI-ARIA tablist
 * "automatic activation" pattern — recommended when, as here, switching panel content has no
 * loading cost: https://www.w3.org/WAI/ARIA/apg/patterns/tabs/), with a roving tabIndex so Tab
 * only stops once, on the active tab, then moves on to the next focusable element outside the
 * tablist. Owns no panel content — a caller pairs the active tab id with its own content switch
 * (see ZimmPdpDrawer).
 *
 * @param props see ZimmTabsProps
 */
export const ZimmTabs = ({ tabs, activeTabId, onTabChange, size, ariaLabel, idPrefix }: ZimmTabsProps) => {
  const styles = useMultiStyleConfig(ZIMM_TABS_RECIPE, { variant: size });
  const listRef = useRef<HTMLDivElement>(null);
  const tabRefs = useRef(new Map<string, HTMLButtonElement>());
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(false);

  const updateOverflow = useCallback(() => {
    const list = listRef.current;
    if (!list) return;
    setCanScrollLeft(list.scrollLeft > 0);
    setCanScrollRight(list.scrollLeft + list.clientWidth < list.scrollWidth - 1);
  }, []);

  // A same-count label swap (Contentful edit, locale switch) changes `scrollWidth` without
  // changing the tablist's own border/content-box dimensions, so ResizeObserver's callback never
  // fires for it — recompute on the labels themselves, not just how many there are.
  const tabsSignature = tabs.map((tab) => `${tab.id}:${tab.label}`).join('|');

  useEffect(() => {
    updateOverflow();
    const list = listRef.current;
    if (!list) return undefined;

    const observer = new ResizeObserver(updateOverflow);
    observer.observe(list);
    list.addEventListener('scroll', updateOverflow);
    return () => {
      observer.disconnect();
      list.removeEventListener('scroll', updateOverflow);
    };
  }, [updateOverflow, tabsSignature]);

  // Move focus to the active tab whenever it changes while focus is already inside the
  // tablist — covers arrow-key navigation; a no-op for a mouse click, which already focuses
  // the clicked button natively.
  useEffect(() => {
    const list = listRef.current;
    if (!list || !list.contains(document.activeElement)) return;
    tabRefs.current.get(activeTabId)?.focus();
  }, [activeTabId]);

  const scrollByOneTab = (direction: 'left' | 'right') => {
    const list = listRef.current;
    if (!list) return;
    const items = Array.from(list.children) as HTMLElement[];
    if (direction === 'right') {
      const next = items.find((item) => item.offsetLeft + item.offsetWidth > list.scrollLeft + list.clientWidth);
      if (next) list.scrollTo({ left: next.offsetLeft, behavior: 'smooth' });
    } else {
      const prev = [...items].reverse().find((item) => item.offsetLeft < list.scrollLeft);
      if (prev) list.scrollTo({ left: prev.offsetLeft, behavior: 'smooth' });
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'Home') {
      e.preventDefault();
      onTabChange(tabs[0].id);
      return;
    }
    if (e.key === 'End') {
      e.preventDefault();
      onTabChange(tabs[tabs.length - 1].id);
      return;
    }
    if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
    e.preventDefault();
    const currentIndex = tabs.findIndex((tab) => tab.id === activeTabId);
    const delta = e.key === 'ArrowRight' ? 1 : -1;
    const nextTab = tabs[(currentIndex + delta + tabs.length) % tabs.length];
    onTabChange(nextTab.id);
  };

  const showOverflowNav = canScrollLeft || canScrollRight;

  return (
    <chakra.div __css={styles.header}>
      <chakra.div ref={listRef} role="tablist" aria-label={ariaLabel} onKeyDown={handleKeyDown} __css={styles.menu}>
        {tabs.map((tab) => {
          const isActive = tab.id === activeTabId;
          return (
            <chakra.button
              key={tab.id}
              ref={(el: HTMLButtonElement | null) => {
                if (el) tabRefs.current.set(tab.id, el);
                else tabRefs.current.delete(tab.id);
              }}
              id={`${idPrefix}-tab-${tab.id}`}
              type="button"
              role="tab"
              aria-selected={isActive}
              aria-controls={`${idPrefix}-panel`}
              tabIndex={isActive ? 0 : -1}
              onClick={() => onTabChange(tab.id)}
              __css={{ ...styles.navItem, ...(isActive ? styles.navItemActive : {}) }}
            >
              {tab.label}
            </chakra.button>
          );
        })}
      </chakra.div>
      {showOverflowNav && (
        <chakra.div __css={styles.navigationIconGroup}>
          <ZimmButton
            variant="icon"
            icon="chevron-left"
            label="Previous tab"
            disabled={!canScrollLeft}
            onClick={() => scrollByOneTab('left')}
          />
          <ZimmButton
            variant="icon"
            icon="chevron-right"
            label="Next tab"
            disabled={!canScrollRight}
            onClick={() => scrollByOneTab('right')}
          />
        </chakra.div>
      )}
    </chakra.div>
  );
};

